import { blankResume } from '../../src/domain/resume';
export function fixture(long=false){const r=blankResume();r.personal.fullName='Анна Соколова';r.personal.targetPosition='Продуктовый дизайнер';r.contacts.email='anna@example.com';r.contacts.phone='+998 90 123 45 67';r.contacts.city='Ташкент';r.summary='Проектирую понятные цифровые продукты. Исследую задачи пользователей, создаю прототипы и проверяю решения вместе с командой.';r.skills=['Figma','Прототипирование','Исследования пользователей','Дизайн-системы'].map(name=>({id:crypto.randomUUID(),name,group:null}));r.experience=Array.from({length:long?5:1},(_,i)=>({id:crypto.randomUUID(),company:`Студия продуктов ${i+1}`,position:'Продуктовый дизайнер',start:`${2024-i}-01`,end:`${2024-i}-12`,current:false,responsibilities:Array.from({length:long?10:2},(_,j)=>j%2?'Проверяла сценарии и собирала обратную связь пользователей.':'Создавала прототипы и обсуждала решения с разработчиками. Работа включала изучение задач, проверку гипотез и подготовку макетов.'),achievements:['Подготовила библиотеку компонентов для команды.']}));r.education=[{id:crypto.randomUUID(),institution:'Университет дизайна',specialty:'Дизайн интерфейсов',level:'Бакалавриат',startYear:2018,endYear:2022,current:false,details:''}];return r;}
